import{_ as n,l as i,o as r,c as l,v as e,p as s,x as t,d as m,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"LoRA 的内在秩","description":"","frontmatter":{"title":"LoRA 的内在秩","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lora-intrinsic-rank.md","filePath":"llm/lora-intrinsic-rank.md","lastUpdated":1789023840000}'),A={name:"llm/lora-intrinsic-rank.md"};function p(_,a,c,L,f,E){const o=i("Mermaid");return r(),l("div",null,[a[1]||(a[1]=e('<h1 id="lora-的内在秩" tabindex="-1">LoRA 的内在秩 <a class="header-anchor" href="#lora-的内在秩" aria-label="Permalink to &quot;LoRA 的内在秩&quot;">​</a></h1><div class="epigraph"><p>微调常常落在很低维的流形上；LoRA 能用，是因为更新的内在维数小，不是因为预训练权重本身可低秩分解。</p><footer>—— Aghajanyan 等，Intrinsic Dimensionality Explains the Effectiveness of Language Model Fine-Tuning（ACL 2021）；Hu 等 LoRA（2021）；Biderman 等（2024）</footer></div><p>从 <a href="/llm/rslora">rsLoRA</a> 到 <a href="/llm/lora-on-moe">MoE 上的 LoRA</a>，本单元改的是参数化与放置。收束课回答：<strong>为什么 \\(r\\ll d\\) 经常够</strong>。Aghajanyan 等人用随机子空间测微调的内在维数（intrinsic dimension），发现许多 NLP 适应只需几百维。Hu 等人把这一观察写成可部署的 \\(BA\\)。Biderman 等人则划出边界：够用时忘得少，不够用时学得少。下一单元不再加适配器，而是<a href="/llm/rome-memit">改一处事实</a>。本课不把 ROME 当低秩方法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全参微调的参数空间是 \\(\\mathbb{R}^P\\)，\\(P\\) 以十亿计。若最优 \\(\\Delta\\theta\\) 实际落在维数 \\(d_{\\mathrm{int}}\\ll P\\) 的子空间，那么任意一张好的投影（LoRA 的因子、VeRA 的随机矩阵、GaLore 的梯度主成分）都能近似这条适应曲线。问题是测量：\\(d_{\\mathrm{int}}\\) 随任务变。风格与指令格式往往很低；从语言模型改成完全不同的目标、或注入大量新事实，则升高。用固定 \\(r=8\\) 覆盖所有任务，是把测量偷换成信仰。</p><p>LoRA 原文强调：低秩的是<strong>更新</strong>，不是 \\(W_0\\)。对 \\(W_0\\) 做 SVD 压缩是另一门课。混为一谈会得出「模型已经低秩所以 LoRA 无损」的错误定理。</p><h3 id="名义-、有效秩、内在维" tabindex="-1">名义 \\(r\\)、有效秩、内在维 <a class="header-anchor" href="#名义-、有效秩、内在维" aria-label="Permalink to &quot;名义 $r$、有效秩、内在维&quot;">​</a></h3><p>名义 \\(r\\) 是因子宽度。有效秩是 \\(BA\\) 奇异值中不可忽略的个数，常小于 \\(r\\)（<a href="/llm/adalora">AdaLoRA</a> 正是为此剪枝）。内在维是任务需要的最小维数，不可观，只能用表现–\\(r\\) 曲线或随机子空间方法估计。三条对不上时：名义很大但有效很小，是优化没打开方向；有效很大仍欠拟合，是 \\(d_{\\mathrm{int}}\\) 超过预算。</p><p><span class="marginnote">Aghajanyan 等人在较小 Transformer 上用 Li 等的 intrinsic dimension 方法：在随机 \\(d\\) 维子空间里微调，看能恢复多少全参性能。曲线的拐点给出操作意义下的 \\(d_{\\mathrm{int}}\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画表现对 \\(r\\) 的曲线，而不是只报一个 \\(r\\)。拐点之后加 \\(r\\) 只加显存。用 <a href="/llm/rslora">rsLoRA</a> 缩放，避免拐点被 \\(\\alpha/r\\) 假造。对学成的 \\(BA\\) 做 SVD：若能量集中在前 2–3 个奇异值，\\(r=16\\) 浪费。任务对比：指令遵循、领域术语、安全拒答各画一条，禁止用平均分选唯一 \\(r\\)。</p><p>若曲线不饱和，选项是：加 \\(r\\)、多插 FFN、全参、<a href="/llm/galore">GaLore</a>/<a href="/llm/relora">ReLoRA</a> 走高秩轨迹，而不是无限加大 \\(\\eta\\)。VeRA 在 \\(d_{\\mathrm{int}}\\) 很小且与随机投影对齐时接近 LoRA；对不齐就应退回可训练因子。</p>',12)),(r(),s(h,null,{default:t(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20D%5B%22%E5%86%85%E5%9C%A8%E7%BB%B4%20d_int%22%5D%0A%20%20D%20--%3E%20LOW%5B%22%E4%BD%8E%EF%BC%9ALoRA%2FVeRA%2FBitFit%20%E5%8F%AF%E8%83%BD%E5%A4%9F%22%5D%0A%20%20D%20--%3E%20HIGH%5B%22%E9%AB%98%EF%BC%9A%E5%8A%A0%20r%20%2F%20%E5%85%A8%E5%8F%82%20%2F%20%E6%97%B6%E9%97%B4%E6%8D%A2%E7%A7%A9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>SFT 工程契约仍在：曲线必须在正确<a href="/llm/chat-template">模板</a>与<a href="/llm/response-only-loss">仅回复</a>上画，否则拐点反映的是格式 bug。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预训练把表示推到对自然语言有用的流形。下游适应常是在流形切空间里走一小段——切空间维数就是 \\(d_{\\mathrm{int}}\\) 的来源直觉。指令 SFT 主要改「如何说话」，切空间更低；<a href="/llm/domain-adaptation-ft">领域 DAPT</a> 要移动流形本身，维数升高。这解释 LIMA 千条与 LoRA \\(r=8\\) 经常同时成立：改接口，不改世界模型。也解释知识注入失败（下单元）：事实编辑需要的方向可能既局部又不满整个 LoRA 子空间，或相反地需要高秩改写许多层。</p><p>Biderman 等人的「学得少、忘得少」是同一几何的两面：走不出低维切空间，既碰不到新技能所需的方向，也碰不到摧毁旧技能的方向。</p><p><span class="marginnote">MoE 上每专家一个切空间，全局 \\(r\\) 不是全局 \\(d_{\\mathrm{int}}\\)。应按专家看 SVD。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>内在维测量昂贵，生产上用 \\(r\\) 扫描代替。扫描必须稳住缩放与 \\(\\eta\\)，否则不是测 \\(d_{\\mathrm{int}}\\)。随机子空间方法依赖各向同性假设，Transformer 里各层宽度不同，数字只能比同一架构。不要把某篇 GLUE 上 \\(d_{\\mathrm{int}}\\approx 200\\) 抄到 70B 工具调用上。</p><p>PEFT 单元到此：尺度（rsLoRA）、更少参数（VeRA）、低秩梯度（GaLore）、层抽样（LISA）、时间换秩（ReLoRA）、偏置（BitFit）、前缀（P-tuning v2）、合并冲突、MoE 放置、内在秩。下一课起，改的不是任务适配器，而是一条事实或一段不该再被生成的知识。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LoRA 有效，因为许多适应的更新内在维低，不是因为 \\(W_0\\) 低秩。</li><li>用表现–\\(r\\) 曲线与 \\(BA\\) 的 SVD 估计是否够用；扫描时用稳定缩放。</li><li>格式与风格通常低维；领域改写与新目标升高维数。</li><li>学得少与忘得少是低维切空间的两面。</li><li>\\(d_{\\mathrm{int}}\\) 超预算时加秩或改全参/时间换秩，不要只加学习率。</li><li>出处：Aghajanyan 等，ACL 2021；Hu 等，LoRA，2021；Biderman 等，LoRA Learns Less and Forgets Less，2024。</li></ul>',10))])}const u=n(A,[["render",p]]);export{B as __pageData,u as default};
